	@Test void lowBudgetPreservesExactKeysAndReleasesAllClaims() throws Exception {
		var manager = LmdbQueryMemoryManager.createForTesting(100_000, 100_000);
		try (var ledger = manager.openQuery()) {
			NativeDistinctTracker tracker = tracker(ledger);
			try {
				long admittedBefore = NativeBudgetedWideDistinct.ADMITTED.get();
				long spillsBefore = NativeExpressionDomain.SPILL_FILES_CREATED.get();
				assertTrue(tracker.add(row(1)));
				assertTrue(ledger.usedBytes() > 0);
				assertEquals(admittedBefore + 1, NativeBudgetedWideDistinct.ADMITTED.get());
				for (int i = 2; i <= 2000; i++) assertTrue(tracker.add(row(i)));
				assertTrue(NativeExpressionDomain.SPILL_FILES_CREATED.get() > spillsBefore);
				for (int i = 1; i <= 2000; i++) assertFalse(tracker.add(row(i)));
				assertTrue(ledger.usedBytes() <= 100_000);
				tracker.clear(); assertTrue(tracker.add(row(1)));
			} finally { close(tracker); }
			assertEquals(0, ledger.usedBytes());
		}
	}

